-- GENERATED by scripts/ddrive_seed.py from the DDRiVE desk-assessment workbook.
-- DDRiVE = Data-Driven Risk and Vulnerability Estimation (renamed from QRE).
-- Source: Ormoc-City-Barangays_Hazard-Assessment_QRE_2026-11-09.xlsx. Reference data only; no personal data (RA 10173).
-- Part 26d (4 of 4 for DDRiVE): run after parts 1-25 and in order. Idempotent; safe to run again.
begin;

on conflict (psgc) do update set social_sensitivity = excluded.social_sensitivity, access_constraints = excluded.access_constraints, coping_capacity = excluded.coping_capacity, adaptive_capacity = excluded.adaptive_capacity, method_source = excluded.method_source, validation_status = excluded.validation_status;

on conflict (psgc) do update set priority_rank = excluded.priority_rank, basis = excluded.basis, population_2024 = excluded.population_2024, confidence = excluded.confidence, validation_status = excluded.validation_status;

on conflict (hazard_event) do update set hazard_family = excluded.hazard_family, exposure_infrastructure = excluded.exposure_infrastructure, exposure_productive = excluded.exposure_productive, exposure_essential = excluded.exposure_essential, exposure_human = excluded.exposure_human, vulnerability_rating = excluded.vulnerability_rating, response_measures = excluded.response_measures, likelihood = excluded.likelihood, severity = excluded.severity, evidence_anchor = excluded.evidence_anchor, validation_status = excluded.validation_status;

on conflict (ranking) do update set severity_min = excluded.severity_min, severity_max = excluded.severity_max, likelihood_min = excluded.likelihood_min, likelihood_max = excluded.likelihood_max, band = excluded.band, label = excluded.label;

on conflict (source_id) do update set name = excluded.name, owner = excluded.owner, url = excluded.url, vintage = excluded.vintage, coverage = excluded.coverage, accessed_on = excluded.accessed_on, limitations = excluded.limitations;

commit;

-- Expected: 85 | 85 | 85 | 85 | 85 | 85 | 10 | 25 | 31
select (select count(*) from public.ddrive_barangay_profiles) as profiles,
       (select count(*) from public.ddrive_flood)             as flood,
       (select count(*) from public.ddrive_hazards)            as hazards,
       (select count(*) from public.ddrive_exposure)         as exposure,
       (select count(*) from public.ddrive_vulnerability)    as vulnerability,
       (select count(*) from public.ddrive_priority)           as priority,
       (select count(*) from public.ddrive_city_scores)      as city_scores,
       (select count(*) from public.ddrive_risk_matrix)        as matrix,
       (select count(*) from public.ddrive_sources)            as sources;
